        let mut out = unsafe { OutCursor::new(buf.as_mut_ptr(), buf.len()) };
        let len = filename_extract_candidate_into(
            b"The.West.Wing.S07E01.The.Ticket.1080p.BluRay.10bit.EAC3.2.0.x265-iVy.mkv",
            &mut out,
        );
